     * Progress arrives as `ImexProgress` events (1000 = done); afterwards
     * call `start_io`.
     */
    func joinSecondDevice(accountId: UInt32, qr: String) async throws 
    
    /**
     * Stores credentials and configures the account (autoconfig fills in the
