/**
 * Events pushed to the UI listener.
 */

public enum VmEvent: Equatable, Hashable {
    
    case accountsChanged
    case chatlistChanged
    case chatChanged(chatId: UInt32
    )
    case incomingMessage(chatId: UInt32, msgId: UInt32
    )
    case configureProgress(permille: UInt32, comment: String?
    )
    /**
     * Import/export progress, e.g. receiving a second-device backup
     * (permille 0 = error/canceled, 1 = started, 1000 = done).
     */
    case imexProgress(permille: UInt32
    )
    case connectivityChanged





}

#if compiler(>=6)
extension VmEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeVmEvent: FfiConverterRustBuffer {
    typealias SwiftType = VmEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> VmEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .accountsChanged
        
        case 2: return .chatlistChanged
        
        case 3: return .chatChanged(chatId: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 4: return .incomingMessage(chatId: try FfiConverterUInt32.read(from: &buf), msgId: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 5: return .configureProgress(permille: try FfiConverterUInt32.read(from: &buf), comment: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 6: return .imexProgress(permille: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 7: return .connectivityChanged
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: VmEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case .accountsChanged:
            writeInt(&buf, Int32(1))
        
        
        case .chatlistChanged:
            writeInt(&buf, Int32(2))
        
        
        case let .chatChanged(chatId):
            writeInt(&buf, Int32(3))
            FfiConverterUInt32.write(chatId, into: &buf)
            
        
        case let .incomingMessage(chatId,msgId):
            writeInt(&buf, Int32(4))
            FfiConverterUInt32.write(chatId, into: &buf)
            FfiConverterUInt32.write(msgId, into: &buf)
            
        
        case let .configureProgress(permille,comment):
            writeInt(&buf, Int32(5))
            FfiConverterUInt32.write(permille, into: &buf)
            FfiConverterOptionString.write(comment, into: &buf)
            
        
        case let .imexProgress(permille):
            writeInt(&buf, Int32(6))
            FfiConverterUInt32.write(permille, into: &buf)
            
        
        case .connectivityChanged:
            writeInt(&buf, Int32(7))
        
        }
    }
}


